(()=>{const track=document.getElementById('sound-track');if(!track)return;const cards=[...track.querySelectorAll('.sound-card')],dots=[...document.querySelectorAll('.sound-dots i')],dialog=document.getElementById('sound-detail');let current=0,pending=false;const details={guitar:{name:'گیتار',family:'ساز زهی · زخمه‌ای',teachers:'استاد حاجیان · استاد سلیمانی (گیتار فلامنکو)',text:'با گیتار می‌توان ملودی و آکورد نواخت و ترانه را همراهی کرد. مسیر عمومی گیتار و فلامنکو یکسان نیست؛ درباره انتخاب مسیر با استاد مشورت کن.',practice:'برای تمرین به ساز مناسب و زمانی منظم نیاز داری. گیتار آکوستیک بی‌صدا نیست؛ شرایط خانه را قبل از خرید در نظر بگیر.'},violin:{name:'ویولن',family:'ساز زهی · آرشه‌ای',teachers:'استاد اکبری',text:'اگر صدای پیوسته و کشیده آرشه را دوست داری، ویولن را از نزدیک امتحان کن. این ساز در موسیقی ایرانی و کلاسیک کاربرد دارد.',practice:'کنترل آرشه، پیدا کردن جای نت‌ها و شنیدن کوک به تمرین پیوسته نیاز دارد. اندازه مناسب ساز را با استاد بررسی کن.'},piano:{name:'پیانو',family:'ساز کلاویه‌ای',teachers:'استاد فروغی',text:'پیانو امکان اجرای ملودی و هارمونی را با دو دست فراهم می‌کند. برای علاقه‌مند به قطعه‌های سازی، همراهی ترانه و شناخت هارمونی مسیر مرتبطی است.',practice:'برای تمرین خانه دسترسی به ساز لازم است. تمرین با هدفون فقط با پیانوی دیجیتال دارای این قابلیت امکان دارد.'},tar:{name:'تار',family:'ساز ایرانی · زهی و زخمه‌ای',teachers:'استاد جعفری',text:'تار یکی از مسیرهای آموزش موسیقی ایرانی است. اگر صدای زخمه و ملودی‌های ایرانی جذب‌ات می‌کند، آن را با سه‌تار و عود هم مقایسه کن.',practice:'گرفتن ساز، مضراب‌زدن و کوک‌کردن را از ابتدا با راهنمایی استاد یاد بگیر. ساز را پیش از مشورت درباره اندازه، کیفیت و بودجه تهیه نکن.'},trumpet:{name:'ترومپت',family:'ساز بادی برنجی',teachers:'استاد اکبری · استاد محسن اکبری',text:'ترومپت صدایی روشن و پرقدرت دارد. شکل‌دادن صدا با نفس و لب‌ها در کنار کار با دریچه‌ها، بخشی از تجربه یادگیری آن است.',practice:'صدای تمرین می‌تواند بلند باشد؛ محل مناسب تمرین را پیش از انتخاب مشخص کن. درباره تولید صدای اولیه از استاد راهنمایی بگیر.'}};
function mark(i){current=i;cards.forEach((c,n)=>c.classList.toggle('sound-active',n===i));dots.forEach((d,n)=>d.classList.toggle('on',n===i));document.getElementById('sound-position').textContent=(i+1).toLocaleString('fa-IR')+' از ۵';document.getElementById('sound-prev').disabled=i===0;document.getElementById('sound-next').disabled=i===cards.length-1}
function center(i,instant=false){i=Math.max(0,Math.min(cards.length-1,i));const t=track.getBoundingClientRect(),c=cards[i].getBoundingClientRect();track.scrollBy({left:c.left+c.width/2-t.left-t.width/2,behavior:instant||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});mark(i)}
track.addEventListener('scroll',()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{const t=track.getBoundingClientRect(),mid=t.left+t.width/2;const distances=cards.map(c=>{const r=c.getBoundingClientRect();return Math.abs(r.left+r.width/2-mid)});mark(distances.indexOf(Math.min(...distances)));pending=false})},{passive:true});document.getElementById('sound-prev').onclick=()=>center(current-1);document.getElementById('sound-next').onclick=()=>center(current+1);track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowLeft'){e.preventDefault();center(current+1)}else if(e.key==='ArrowRight'){e.preventDefault();center(current-1)}});
function close(){dialog.close();document.body.style.overflow=''}dialog.querySelector('.sound-detail-close').onclick=close;dialog.addEventListener('cancel',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog)close()});document.querySelectorAll('[data-learn]').forEach(button=>button.onclick=()=>{const key=button.dataset.learn,d=details[key];document.getElementById('sound-detail-body').innerHTML=`<div class="detail-photo"><img src="photos/${key}.webp" alt="عکس واقعی ${d.name}"></div><div class="detail-copy"><span>${d.family}</span><h2 id="sound-detail-title">${d.name} را بیشتر بشناس</h2><p>${d.text}</p><div class="detail-teacher"><small>مدرس مرتبط در آموزشگاه</small><strong>${d.teachers}</strong></div><h3>قبل از شروع</h3><p>${d.practice}</p><a href="#contact" class="detail-contact">برای ظرفیت و زمان کلاس با دفتر هماهنگ کن ↗</a><small class="detail-note">عکس برای معرفی ساز است و نشان‌دهنده تجهیزات آموزشگاه نیست.</small></div>`;dialog.querySelector('.detail-contact').onclick=close;dialog.showModal();document.body.style.overflow='hidden'});center(1,true);
})();
